{
  "workflow": {
    "activities": [
      {
        "id": "A1",
        "name": "Submit Measurement Request",
        "actor": "Requester",
        "system": "unknown",
        "inputs": ["measurement request", "wafer identifier"],
        "outputs": ["submitted measurement request"]
      },
      {
        "id": "A2",
        "name": "Confirm Request and Wafer Identifier",
        "actor": "Measurement Engineer",
        "system": "unknown",
        "inputs": ["submitted measurement request", "wafer identifier"],
        "outputs": ["confirmed request"]
      },
      {
        "id": "A3",
        "name": "Select Measurement Equipment",
        "actor": "Measurement Engineer",
        "system": "unknown",
        "inputs": ["confirmed request", "measurement type", "wafer condition", "equipment qualification status"],
        "outputs": ["selected equipment (A, B, or C)"]
      },
      {
        "id": "A4",
        "name": "Check Equipment Availability and Reserve Slot",
        "actor": "Measurement Engineer",
        "system": "Equipment Reservation System",
        "inputs": ["selected equipment"],
        "outputs": ["reserved equipment slot"]
      },
      {
        "id": "A5",
        "name": "Prepare Wafer per Equipment-Specific Procedure",
        "actor": "Measurement Engineer",
        "system": "unknown",
        "inputs": ["reserved equipment slot", "wafer", "equipment-specific preparation procedure"],
        "outputs": ["prepared wafer"]
      },
      {
        "id": "A6",
        "name": "Run Measurement Recipe",
        "actor": "Measurement Engineer",
        "system": "unknown",
        "inputs": ["prepared wafer", "measurement recipe"],
        "outputs": ["raw measurement output"]
      },
      {
        "id": "A7",
        "name": "Validate Measurement Output",
        "actor": "Measurement Engineer",
        "system": "unknown",
        "inputs": ["raw measurement output"],
        "outputs": ["validation decision (valid or invalid/noisy)"]
      },
      {
        "id": "A8",
        "name": "Upload Measurement Result to Repository",
        "actor": "Measurement Engineer",
        "system": "Measurement Result Repository",
        "inputs": ["validated measurement output"],
        "outputs": ["stored measurement result", "equipment usage record"]
      },
      {
        "id": "A9",
        "name": "Send Request Completion Notice",
        "actor": "Measurement Engineer",
        "system": "unknown",
        "inputs": ["stored measurement result"],
        "outputs": ["completion notification to requester"]
      },
      {
        "id": "A10",
        "name": "Handle Invalid Measurement Exception",
        "actor": "Measurement Engineer",
        "system": "unknown",
        "inputs": ["invalid/noisy measurement output"],
        "outputs": ["exception record"]
      }
    ],
    "decisions": [
      {
        "id": "D1",
        "condition": "Is equipment available and qualified for the selected tool?",
        "branches": [
          "Equipment available and qualified → proceed to A5",
          "Equipment unavailable or unqualified → return to A3 to select alternative equipment"
        ]
      },
      {
        "id": "D2",
        "condition": "Is the measurement output valid (not invalid or noisy)?",
        "branches": [
          "Valid → proceed to A8",
          "Invalid/Noisy → proceed to A10 (exception handling)"
        ]
      }
    ],
    "exceptions": [
      {
        "id": "E1",
        "name": "Invalid Measurement Output",
        "trigger": "Measurement output deemed invalid or noisy during validation (A7)",
        "handling_activity": "A10",
        "resolution": "unknown — downstream handling steps after exception recording are not specified"
      },
      {
        "id": "E2",
        "name": "No Qualified Equipment Available",
        "trigger": "No equipment of the required type is available or qualified at time of selection",
        "handling_activity": "D1 branch back to A3",
        "resolution": "Engineer selects alternative equipment or process is delayed; escalation path not specified"
      }
    ],
    "dependencies": [
      {"from": "A1", "to": "A2", "type": "control_flow"},
      {"from": "A2", "to": "A3", "type": "control_flow"},
      {"from": "A3", "to": "A4", "type": "control_flow"},
      {"from": "A4", "to": "D1", "type": "control_flow"},
      {"from": "D1", "to": "A5", "type": "control_flow"},
      {"from": "D1", "to": "A3", "type": "control_flow"},
      {"from": "A5", "to": "A6", "type": "control_flow"},
      {"from": "A6", "to": "A7", "type": "control_flow"},
      {"from": "A7", "to": "D2", "type": "control_flow"},
      {"from": "D2", "to": "A8", "type": "control_flow"},
      {"from": "D2", "to": "A10", "type": "control_flow"},
      {"from": "A8", "to": "A9", "type": "control_flow"}
    ]
  },
  "automation_opportunities": [
    {
      "target": "A3 — Select Measurement Equipment",
      "rationale": "Equipment selection is currently a manual decision by the engineer. An automated recommendation engine could use measurement type, wafer condition, and real-time equipment qualification and availability data to suggest or assign the optimal tool, reducing decision time and selection errors.",
      "required_data": ["measurement type", "wafer condition", "equipment qualification status", "real-time equipment availability"],
      "constraints": ["Equipment qualification rules must be formally encoded", "Engineer override capability should be preserved for edge cases"],
      "confidence": "medium"
    },
    {
      "target": "A4 — Check Equipment Availability and Reserve Slot",
      "rationale": "Availability checking and slot reservation are well-suited to automation via an equipment reservation system, eliminating manual coordination and reducing scheduling conflicts.",
      "required_data": ["equipment schedules", "equipment qualification status", "requested time window"],
      "constraints": ["Requires a live equipment reservation system with up-to-date status feeds"],
      "confidence": "high"
    },
    {
      "target": "A7 — Validate Measurement Output",
      "rationale": "Validation of measurement output could be automated using rule-based thresholds or statistical/ML models trained on historical measurement data, reducing reliance on engineer judgment for routine cases.",
      "required_data": ["raw measurement output", "historical measurement data", "defined acceptance thresholds or trained model"],
      "constraints": ["Numeric thresholds are not currently defined and must be established", "Model training requires sufficient historical labeled data", "Engineer review should remain available for borderline cases"],
      "confidence": "medium"
    },
    {
      "target": "A8 — Upload Measurement Result to Repository",
      "rationale": "If the measurement tool supports automatic data capture, the upload step could be fully automated, eliminating manual entry errors and reducing cycle time.",
      "required_data": ["tool output format", "repository API or integration interface"],
      "constraints": ["Automatic capture capability is unconfirmed for all tool types", "Data format standardization across tool types A, B, C may be required"],
      "confidence": "medium"
    },
    {
      "target": "A9 — Send Request Completion Notice",
      "rationale": "Completion notification to the requester can be automated as a triggered event upon successful upload to the repository, removing a manual communication step.",
      "required_data": ["requester contact information", "upload confirmation event from repository"],
      "constraints": ["Notification system must be integrated with the measurement result repository"],
      "confidence": "high"
    }
  ],
  "remaining_gaps": [
    {
      "id": "G1",
      "description": "Equipment-specific preparation and calibration steps for tool types A, B, and C are not defined. The discrete ordered steps for each variant are unknown."
    },
    {
      "id": "G2",
      "description": "The exact method of measurement result capture (manual engineer entry vs. automatic tool capture) is not specified, and may differ by tool type."
    },
    {
      "id": "G3",
      "description": "Numeric or categorical acceptance thresholds for measurement output validation are not defined. It is unknown what criteria distinguish a valid result from an invalid or noisy one."
    },
    {
      "id": "G4",
      "description": "The equipment owner's role and specific intervention points in the workflow are not detailed."
    },
    {
      "id": "G5",
      "description": "The resolution path after an invalid measurement exception (E1) is recorded is not specified — it is unknown whether the wafer is re-measured, escalated, or scrapped."
    },
    {
      "id": "G6",
      "description": "The system used to submit and track measurement requests (A1) is not identified."
    },
    {
      "id": "G7",
      "description": "The system used to send completion notifications (A9) is not identified."
    },
    {
      "id": "G8",
      "description": "It is unclear whether the equipment reservation system is a dedicated software system or an informal manual process."
    },
    {
      "id": "G9",
      "description": "The escalation or waiting policy when no qualified equipment is available (E2) is not specified — it is unknown how long the process waits or who is notified."
    }
  ]
}
